import re
import json

def extract_json_from_llm_response(text: str) -> dict:
    """Extracts and parses JSON object embedded inside markdown or text."""
    # Pattern to match json code blocks or raw bracketed json
    pattern = r'`(?:json)?\s*([\{\[].*?[\}\]])\s*`'
    match = re.search(pattern, text, re.DOTALL)

    raw_json = match.group(1) if match else text.strip()
    try:
        return json.loads(raw_json)
    except json.JSONDecodeError:
        # Fallback search for first { to last }
        curly_match = re.search(r'\{.*\}', text, re.DOTALL)
        if curly_match:
            return json.loads(curly_match.group(0))
        raise ValueError('Could not parse valid JSON from LLM output.')

raw_output = '''Sure, here is your tool call:
`json
{
  "tool": "search_weather",
  "params": {"city": "Bengaluru"}
}
`
Let me know if you need anything else!'''

parsed = extract_json_from_llm_response(raw_output)
print('Successfully parsed:', parsed)
